  background: var(--color-primary);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 1000;
  transition: top 0.1s;
}
.skip-link:focus { top: 0.75rem; }

/* ── Header ───────────────────────────────────────────────────── */
.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}
.header-inner {
  max-width: 960px;
  margin: 0 auto;
  padding: 0.875rem 1.5rem;
}
.logo {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 700;
  font-size: 1.125rem;
  color: var(--color-text);
  text-decoration: none;
}

/* ── Page layout ──────────────────────────────────────────────── */
main { outline: none; }

.page-container {
  max-width: 560px;
  margin: 0 auto;
  padding: 3rem 1.25rem 4rem;
}

/* ── Card ─────────────────────────────────────────────────────── */
.form-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2.5rem 2rem;
}

@media (max-width: 479px) {
  .form-card { padding: 2rem 1.25rem; }
}

/* ── Form header ──────────────────────────────────────────────── */
.form-header { margin-bottom: 1.75rem; }

h1 {
  font-size: 1.625rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.25;
  margin-bottom: 0.375rem;
}

.form-subtitle {
  color: var(--color-text-muted);
  font-size: 0.9375rem;
}

/* ── Required note ────────────────────────────────────────────── */
.required-note {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1.5rem;
}
.required-note span {
  color: var(--color-error);
  font-weight: 700;
}

/* ── Form fields ──────────────────────────────────────────────── */
form { display: flex; flex-direction: column; gap: 1.25rem; }

.form-field { display: flex; flex-direction: column; gap: 0.375rem; }

label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-text);
}

.required-marker {
  color: var(--color-error);
  margin-left: 0.125rem;
}

.optional-marker {
  font-weight: 400;
  color: var(--color-text-muted);
  font-size: 0.875rem;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  width: 100%;
  padding: 0.625rem 0.875rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  font-family: inherit;
  font-size: 1rem;
  color: var(--color-text);
  background: var(--color-surface);
  transition: border-color 0.15s, box-shadow 0.15s;
  appearance: none;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
  outline: none;
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.18);
}

input[aria-invalid="true"] {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}

input[aria-invalid="true"]:focus {
  border-color: var(--color-error);
  box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.16);
}

/* ── Help & error text ────────────────────────────────────────── */
.field-help {
  font-size: 0.8125rem;
  color: var(--color-help);
  line-height: 1.45;
}

.field-error {
  font-size: 0.8125rem;
  color: var(--color-error);
  font-weight: 500;
  min-height: 0;           /* collapses when empty */
  line-height: 1.45;
}

.field-error:empty { display: none; }

/* ── Submit button ────────────────────────────────────────────── */
.btn-submit {
  margin-top: 0.5rem;
  padding: 0.75rem 1.5rem;
  background: var(--color-primary);
  color: #fff;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background-color 0.15s, transform 0.1s;
  align-self: flex-start;
}

.btn-submit:hover { background: var(--color-primary-hover); }

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

.btn-submit:active { transform: scale(0.98); }

/* ── Success banner ───────────────────────────────────────────── */
.success-banner {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-top: 1.5rem;
  padding: 1rem 1.125rem;
  background: var(--color-success-bg);
  border: 1px solid #bbf7d0;
  border-radius: var(--radius-md);
}

.success-banner[hidden] { display: none; }

.success-banner p {
  font-size: 0.9375rem;
  font-weight: 500;
  color: #166534;
}

/* ── Screen-reader only ───────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Reduced motion ───────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Forced colors ────────────────────────────────────────────── */
@media (forced-colors: active) {
  input[type="text"],
  input[type="email"],
  input[type="tel"] { forced-color-adjust: auto; }

  .btn-submit { forced-color-adjust: none; border: 2px solid ButtonText; }
}

/* ── Narrow viewport / reflow ────────────────────────────────── */
@media (max-width: 320px) {
  .form-card { padding: 1.5rem 1rem; }
  h1 { font-size: 1.375rem; }
  .btn-submit { width: 100%; align-self: stretch; }
}
