.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}
.header-inner {
  max-width: 960px;
  margin: 0 auto;
  padding: 0.875rem 1.5rem;
}
.logo {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 700;
  font-size: 1.125rem;
  color: var(--color-text);
  text-decoration: none;
}

/* ── Page layout ──────────────────────────────────────────────── */
main { outline: none; }

.page-container {
  max-width: 560px;
  margin: 0 auto;
  padding: 3rem 1.25rem 4rem;
}

/* ── Card ─────────────────────────────────────────────────────── */
.form-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2.5rem 2rem;
}

@media (max-width: 479px) {
  .form-card { padding: 2rem 1.25rem; }
}

/* ── Form header ──────────────────────────────────────────────── */
.form-header { margin-bottom: 1.75rem; }

h1 {
  font-size: 1.625rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.25;
  margin-bottom: 0.375rem;
}

.form-subtitle {
  color: var(--color-text-muted);
  font-size: 0.9375rem;
}

/* ── Required note ────────────────────────────────────────────── */
.required-note {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1.5rem;
}
.required-note span {
  color: var(--color-error);
  font-weight: 700;
}

/* ── Form fields ──────────────────────────────────────────────── */
form { display: flex; flex-direction: column; gap: 1.25rem; }

.form-field { display: flex; flex-direction: column; gap: 0.375rem; }

label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-text);
}

.required-marker {
  color: var(--color-error);
  margin-left: 0.125rem;
}

.optional-marker {
  font-weight: 400;
  color: var(--color-text-muted);
  font-size: 0.875rem;
}

input[type="text"],
input[type="email"],
