  font-size: 0.875rem;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  width: 100%;
  padding: 0.625rem 0.875rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  font-family: inherit;
  font-size: 1rem;
  color: var(--color-text);
  background: var(--color-surface);
  transition: border-color 0.15s, box-shadow 0.15s;
  appearance: none;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
  outline: none;
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.18);
}

input[aria-invalid="true"] {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}

input[aria-invalid="true"]:focus {
  border-color: var(--color-error);
  box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.16);
}

/* ── Help & error text ────────────────────────────────────────── */
.field-help {
  font-size: 0.8125rem;
  color: var(--color-help);
  line-height: 1.45;
}

.field-error {
  font-size: 0.8125rem;
  color: var(--color-error);
  font-weight: 500;
  min-height: 0;           /* collapses when empty */
  line-height: 1.45;
}

.field-error:empty { display: none; }

/* ── Submit button ────────────────────────────────────────────── */
.btn-submit {
  margin-top: 0.5rem;
  padding: 0.75rem 1.5rem;
  background: var(--color-primary);
  color: #fff;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background-color 0.15s, transform 0.1s;
  align-self: flex-start;
}

.btn-submit:hover { background: var(--color-primary-hover); }

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

.btn-submit:active { transform: scale(0.98); }

/* ── Success banner ───────────────────────────────────────────── */
.success-banner {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-top: 1.5rem;
  padding: 1rem 1.125rem;
  background: var(--color-success-bg);
  border: 1px solid #bbf7d0;
  border-radius: var(--radius-md);
}

.success-banner[hidden] { display: none; }

.success-banner p {
  font-size: 0.9375rem;
  font-weight: 500;
  color: #166534;
}

/* ── Screen-reader only ───────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Reduced motion ───────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Forced colors ────────────────────────────────────────────── */
@media (forced-colors: active) {
  input[type="text"],
  input[type="email"],
  input[type="tel"] { forced-color-adjust: auto; }

  .btn-submit { forced-color-adjust: none; border: 2px solid ButtonText; }
}

/* ── Narrow viewport / reflow ────────────────────────────────── */
@media (max-width: 320px) {
  .form-card { padding: 1.5rem 1rem; }
  h1 { font-size: 1.375rem; }
  .btn-submit { width: 100%; align-self: stretch; }
}
